#!/usr/bin/env bash
# Regenerates crates/apis/src/generated from the CRDs of the external API kinds the operator uses.
# (This repository's own API, `apis::provisioning::v1alpha1`, is hand-maintained in
# crates/apis/src/provisioning_types.rs alongside config/crd/bases.)
#
#   1. collect CRD YAMLs:
#        - config/crd/external   (doca-platform provisioning/dpuservice, hypershift; checked in,
#                                 regenerated by hack/gen-external-crds.sh)
#        - controller-gen over the Go API packages for doca-platform operator, metallb and
#          openshift config/v1 (no CRDs for those are checked in)
#   2. run kopium on every CRD (structure + documentation)
#   3. post-process with hack/gen-rust-apis (a standalone Go module): re-shape the kopium output
#      against the Go API types so that serde reproduces Go's encoding/json byte for byte
#      (field order, omitempty, nil -> null, Go type names), add unknown-field preservation,
#      Go constants and ctrlrt::impl_resource! registrations.
#   4. rustfmt
#
# The upstream Go API versions are pinned in hack/gen-rust-apis/go.mod and fetched from the Go
# module proxy (nothing is vendored); controller-gen `paths=` resolve against that module.
# Tools are installed into target/apis/tools (kopium via cargo, controller-gen via go).
# See crates/apis/GENERATION.md for the list of post-processing overrides.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "${ROOT}"

KOPIUM_VERSION="${KOPIUM_VERSION:-0.24.1}"
CONTROLLER_TOOLS_VERSION="${CONTROLLER_TOOLS_VERSION:-v0.18.0}"
TOOLS="${ROOT}/target/apis/tools"
KOPIUM="${TOOLS}/bin/kopium"
CONTROLLER_GEN="${TOOLS}/bin/controller-gen"
GEN_MODULE="${ROOT}/hack/gen-rust-apis"
OUT="${ROOT}/crates/apis/src/generated"

if [[ ! -x "${KOPIUM}" ]] || ! "${KOPIUM}" --version | grep -q "${KOPIUM_VERSION}"; then
  CARGO_TARGET_DIR="${ROOT}/target/apis" cargo install kopium --locked --version "${KOPIUM_VERSION}" --root "${TOOLS}"
fi
if [[ ! -x "${CONTROLLER_GEN}" ]] || ! "${CONTROLLER_GEN}" --version | grep -q "${CONTROLLER_TOOLS_VERSION}"; then
  GOBIN="${TOOLS}/bin" go install "sigs.k8s.io/controller-tools/cmd/controller-gen@${CONTROLLER_TOOLS_VERSION}"
fi

WORK="$(mktemp -d)"
trap 'rm -rf "${WORK}"' EXIT
mkdir -p "${WORK}/crds" "${WORK}/kopium"

CRDS=(
  config/crd/bases/provisioning.dpu.hcp.io_dpfhcpprovisioners.yaml
  config/crd/external/provisioning.dpu.nvidia.com_dpus.yaml
  config/crd/external/provisioning.dpu.nvidia.com_dpuclusters.yaml
  config/crd/external/provisioning.dpu.nvidia.com_dpuflavors.yaml
  config/crd/external/svc.dpu.nvidia.com_dpudeployments.yaml
  config/crd/external/svc.dpu.nvidia.com_dpuservicetemplates.yaml
  config/crd/external/hypershift.openshift.io_hostedclusters.yaml
  config/crd/external/hypershift.openshift.io_nodepools.yaml
)
cp "${CRDS[@]}" "${WORK}/crds/"

GEN="${WORK}/controller-gen"
mkdir -p "${GEN}"
for pkg in \
  github.com/nvidia/doca-platform/api/operator/v1alpha1/... \
  go.universe.tf/metallb/api/v1beta1/... \
  github.com/openshift/api/config/v1; do
  (cd "${GEN_MODULE}" && GOFLAGS=-mod=readonly "${CONTROLLER_GEN}" crd paths="${pkg}" output:crd:dir="${GEN}")
done
cp "${GEN}/operator.dpu.nvidia.com_dpfoperatorconfigs.yaml" \
   "${GEN}/metallb.io_ipaddresspools.yaml" \
   "${GEN}/metallb.io_l2advertisements.yaml" \
   "${GEN}/config.openshift.io_clusterversions.yaml" \
   "${WORK}/crds/"

for crd in "${WORK}"/crds/*.yaml; do
  name="$(basename "${crd}" .yaml)"
  "${KOPIUM}" -f "${crd}" --hide-kube --docs --derive Default --derive PartialEq --no-condition --no-object-reference > "${WORK}/kopium/${name}.rs"
done

rm -rf "${OUT}"
(cd "${GEN_MODULE}" && GOFLAGS=-mod=readonly go run . -crds "${WORK}/crds" -kopium "${WORK}/kopium" -out "${OUT}")
rustfmt --edition 2024 "${OUT}"/*.rs
echo "generated ${OUT}"
